import React, { useEffect, useState } from 'react';
import { DndContext, closestCenter, PointerSensor, useSensor, useSensors } from '@dnd-kit/core';
import { SortableContext, horizontalListSortingStrategy, arrayMove, useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { Plus, Copy, Trash2, Play, Pause, Shuffle, Eraser, Pipette } from 'lucide-react';
import LedStripPreview from '../shared/LedStripPreview';

const PRESET_SWATCHES = [
  '#ffffff', '#ff2d95', '#7c3aed', '#00f5d4', '#ffb703', '#ff0054',
  '#06d6a0', '#118ab2', '#f15bb5', '#fee440', '#9b5de5', '#111111',
];
const OFF_COLOR = '#141414';
const DEFAULT_DURATION = 200;

function makeBlankFrame(ledCount, fill = OFF_COLOR) {
  return { colors: Array.from({ length: ledCount }, () => fill), duration: DEFAULT_DURATION };
}

function resizeColors(colors, ledCount) {
  const next = colors.slice(0, ledCount);
  while (next.length < ledCount) next.push(OFF_COLOR);
  return next;
}

// Frame-by-frame timeline editor — full "Sequence" patterns when multiple
// frames are used, or (with `singleFrame`) the "Static Colour / Per-Pixel"
// mode: exactly one frame, no timeline controls. Two device concepts, one
// implementation, matching the plan's decision not to build a separate
// per-pixel editor.
export default function SequenceEditor({ initial, onChange, singleFrame = false, className = '' }) {
  const [ledCount, setLedCount] = useState(initial?.ledCount || 30);
  const [frames, setFrames] = useState(
    initial?.frames?.length ? initial.frames : [makeBlankFrame(initial?.ledCount || 30)]
  );
  const [activeIdx, setActiveIdx] = useState(0);
  const [paintColor, setPaintColor] = useState('#ffffff');
  const [playing, setPlaying] = useState(false);

  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 4 } }));

  // Keep every frame's pixel count in sync with ledCount.
  useEffect(() => {
    setFrames((fr) => fr.map((f) => ({ ...f, colors: resizeColors(f.colors, ledCount) })));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ledCount]);

  useEffect(() => {
    onChange?.({ ledCount, frames });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ledCount, JSON.stringify(frames)]);

  const activeFrame = frames[Math.min(activeIdx, frames.length - 1)];

  function paintPixel(i) {
    setFrames((fr) =>
      fr.map((f, idx) => (idx === activeIdx ? { ...f, colors: f.colors.map((c, ci) => (ci === i ? paintColor : c)) } : f))
    );
  }

  function fillActiveFrame(color) {
    setFrames((fr) =>
      fr.map((f, idx) => (idx === activeIdx ? { ...f, colors: f.colors.map(() => color) } : f))
    );
  }

  function randomiseActiveFrame() {
    setFrames((fr) =>
      fr.map((f, idx) =>
        idx === activeIdx
          ? { ...f, colors: f.colors.map(() => PRESET_SWATCHES[Math.floor(Math.random() * (PRESET_SWATCHES.length - 1))]) }
          : f
      )
    );
  }

  function setActiveDuration(ms) {
    setFrames((fr) => fr.map((f, idx) => (idx === activeIdx ? { ...f, duration: ms } : f)));
  }

  function addFrame() {
    setFrames((fr) => {
      const copy = [...fr, { ...activeFrame, colors: [...activeFrame.colors] }];
      setActiveIdx(copy.length - 1);
      return copy;
    });
  }

  function deleteFrame(idx) {
    setFrames((fr) => {
      if (fr.length <= 1) return fr;
      const next = fr.filter((_, i) => i !== idx);
      setActiveIdx((cur) => Math.min(cur, next.length - 1));
      return next;
    });
  }

  function handleDragEnd(event) {
    const { active, over } = event;
    if (!over || active.id === over.id) return;
    setFrames((fr) => {
      const oldIndex = fr.findIndex((_, i) => `f-${i}` === active.id);
      const newIndex = fr.findIndex((_, i) => `f-${i}` === over.id);
      if (oldIndex === -1 || newIndex === -1) return fr;
      const reordered = arrayMove(fr, oldIndex, newIndex);
      setActiveIdx(newIndex);
      return reordered;
    });
  }

  const avgDuration = frames.reduce((sum, f) => sum + (f.duration || DEFAULT_DURATION), 0) / frames.length;
  const previewSpeed = Math.min(5, Math.max(0.1, 400 / avgDuration));
  const frameIds = frames.map((_, i) => `f-${i}`);

  return (
    <div className={className}>
      <div className="mb-4">
        <LedStripPreview
          ledCount={ledCount}
          colors={playing ? undefined : activeFrame.colors}
          frames={playing && frames.length > 1 ? frames : undefined}
          speed={previewSpeed}
          height={40}
        />
        {frames.length > 1 && (
          <button
            type="button"
            onClick={() => setPlaying((p) => !p)}
            className="mt-2 inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm bg-neutral-900 border border-neutral-700 text-neutral-300 hover:border-neutral-500"
          >
            {playing ? <Pause className="w-3.5 h-3.5" /> : <Play className="w-3.5 h-3.5" />}
            {playing ? 'Pause preview' : 'Play preview'}
          </button>
        )}
      </div>

      <div className="mb-4 flex items-center gap-3">
        <label className="text-sm text-neutral-400">LED count</label>
        <input
          type="number"
          min={1}
          max={300}
          value={ledCount}
          onChange={(e) => setLedCount(Math.max(1, Math.min(300, parseInt(e.target.value, 10) || 1)))}
          className="w-20 px-2 py-1 bg-neutral-900 border border-neutral-700 rounded-md text-white text-sm"
        />
      </div>

      {!singleFrame && (
        <div className="mb-4">
          <label className="block text-sm text-neutral-400 mb-2">
            Frames ({frames.length}) — drag to reorder
          </label>
          <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
            <SortableContext items={frameIds} strategy={horizontalListSortingStrategy}>
              <div className="flex flex-wrap gap-2">
                {frames.map((f, i) => (
                  <FrameChip
                    key={frameIds[i]}
                    id={frameIds[i]}
                    frame={f}
                    ledCount={ledCount}
                    active={i === activeIdx}
                    onSelect={() => setActiveIdx(i)}
                    onDelete={() => deleteFrame(i)}
                    removable={frames.length > 1}
                  />
                ))}
                <button
                  type="button"
                  onClick={addFrame}
                  className="w-14 h-10 rounded-md border border-dashed border-neutral-600 text-neutral-400 hover:border-cyan-500 hover:text-cyan-400 flex items-center justify-center"
                  title="Duplicate current frame"
                >
                  <Plus className="w-4 h-4" />
                </button>
              </div>
            </SortableContext>
          </DndContext>
        </div>
      )}

      {!singleFrame && (
        <div className="mb-4">
          <div className="flex justify-between text-sm text-neutral-400 mb-1">
            <span>Frame duration</span>
            <span>{activeFrame.duration} ms</span>
          </div>
          <input
            type="range"
            min={50}
            max={2000}
            step={10}
            value={activeFrame.duration}
            onChange={(e) => setActiveDuration(parseInt(e.target.value, 10))}
            className="w-full accent-cyan-500"
          />
        </div>
      )}

      <div className="mb-3">
        <div className="flex items-center justify-between mb-2">
          <label className="text-sm text-neutral-400">Paint colour</label>
          <div className="flex gap-1.5">
            <button
              type="button"
              onClick={() => fillActiveFrame(paintColor)}
              className="p-1.5 rounded-md bg-neutral-900 border border-neutral-700 text-neutral-300 hover:border-neutral-500"
              title="Fill frame with paint colour"
            >
              <Copy className="w-3.5 h-3.5" />
            </button>
            <button
              type="button"
              onClick={randomiseActiveFrame}
              className="p-1.5 rounded-md bg-neutral-900 border border-neutral-700 text-neutral-300 hover:border-neutral-500"
              title="Randomise frame"
            >
              <Shuffle className="w-3.5 h-3.5" />
            </button>
            <button
              type="button"
              onClick={() => fillActiveFrame(OFF_COLOR)}
              className="p-1.5 rounded-md bg-neutral-900 border border-neutral-700 text-neutral-300 hover:border-neutral-500"
              title="Clear frame"
            >
              <Eraser className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>
        <div className="flex flex-wrap gap-1.5 items-center">
          {PRESET_SWATCHES.map((hex) => (
            <button
              key={hex}
              type="button"
              onClick={() => setPaintColor(hex)}
              className={`w-6 h-6 rounded-md border-2 ${paintColor === hex ? 'border-cyan-400' : 'border-neutral-700'}`}
              style={{ backgroundColor: hex }}
              title={hex}
            />
          ))}
          <div className="relative w-6 h-6" title="Custom colour…">
            <input
              type="color"
              value={paintColor}
              onChange={(e) => setPaintColor(e.target.value)}
              className="w-6 h-6 rounded-md border-2 border-dashed border-neutral-500 bg-transparent cursor-pointer"
            />
            {/* Shows the current colour like the swatches do, but the dashed
                border + icon mark it as the custom picker, not another preset
                or a "currently selected" indicator. mix-blend-difference keeps
                the icon visible no matter what colour is picked. */}
            <Pipette className="w-3 h-3 text-white absolute inset-0 m-auto pointer-events-none mix-blend-difference" />
          </div>
        </div>
      </div>

      <div>
        <label className="block text-sm text-neutral-400 mb-2">
          {singleFrame ? 'Pixels' : `Pixels — frame ${activeIdx + 1}`}
        </label>
        <div className="flex flex-wrap gap-1 p-2 bg-neutral-950 rounded-lg border border-neutral-800">
          {activeFrame.colors.map((hex, i) => (
            <button
              key={i}
              type="button"
              onClick={() => paintPixel(i)}
              className="w-5 h-5 rounded-sm border border-neutral-800 hover:border-cyan-400"
              style={{ backgroundColor: hex }}
              title={`LED ${i + 1}`}
            />
          ))}
        </div>
      </div>
    </div>
  );
}

function FrameChip({ id, frame, ledCount, active, onSelect, onDelete, removable }) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id });
  const style = { transform: CSS.Transform.toString(transform), transition, opacity: isDragging ? 0.6 : 1 };
  return (
    <div
      ref={setNodeRef}
      style={style}
      {...attributes}
      {...listeners}
      onClick={onSelect}
      className={`relative group w-14 h-10 rounded-md overflow-hidden border-2 cursor-grab ${
        active ? 'border-cyan-400' : 'border-neutral-700'
      }`}
    >
      <div className="flex w-full h-full">
        {frame.colors.slice(0, Math.min(ledCount, 14)).map((c, i) => (
          <div key={i} className="flex-1" style={{ backgroundColor: c }} />
        ))}
      </div>
      {removable && (
        <button
          type="button"
          onClick={(e) => {
            e.stopPropagation();
            onDelete();
          }}
          onPointerDown={(e) => e.stopPropagation()}
          className="absolute -top-1.5 -right-1.5 w-4 h-4 rounded-full bg-neutral-800 border border-neutral-600 text-neutral-300 opacity-0 group-hover:opacity-100 flex items-center justify-center"
        >
          <Trash2 className="w-2.5 h-2.5" />
        </button>
      )}
    </div>
  );
}
