import React, { useEffect, useState } from 'react';
import { DndContext, closestCenter, PointerSensor, useSensor, useSensors } from '@dnd-kit/core';
import { SortableContext, horizontalListSortingStrategy, arrayMove, useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { X, Plus } from 'lucide-react';
import LedStripPreview from '../shared/LedStripPreview';

const MAX_COLORS = 24;

// Controlled editor for a PaletteScroll / PaletteFlash pattern: a
// user-defined, reorderable color list plus a style toggle and speed.
export default function PaletteEditor({ initial, onChange, className = '' }) {
  const [colors, setColors] = useState(
    initial?.colors?.length ? initial.colors : ['#ff2d95', '#7c3aed', '#00f5d4']
  );
  const [style, setStyle] = useState(initial?.style || 'scroll');
  const [speed, setSpeed] = useState(initial?.speed ?? 1.0);

  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 4 } }));

  useEffect(() => {
    onChange?.({ style, colors, speed });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [style, JSON.stringify(colors), speed]);

  function handleDragEnd(event) {
    const { active, over } = event;
    if (!over || active.id === over.id) return;
    setColors((cur) => {
      const oldIndex = cur.findIndex((_, i) => `c-${i}` === active.id);
      const newIndex = cur.findIndex((_, i) => `c-${i}` === over.id);
      return oldIndex === -1 || newIndex === -1 ? cur : arrayMove(cur, oldIndex, newIndex);
    });
  }

  function addColor() {
    setColors((c) => (c.length >= MAX_COLORS ? c : [...c, '#ffffff']));
  }
  function removeColor(idx) {
    setColors((c) => (c.length > 1 ? c.filter((_, i) => i !== idx) : c));
  }
  function setColor(idx, hex) {
    setColors((c) => c.map((v, i) => (i === idx ? hex : v)));
  }

  const ids = colors.map((_, i) => `c-${i}`);

  return (
    <div className={className}>
      <div className="mb-4">
        <LedStripPreview colors={colors} paletteStyle={style} speed={speed} />
      </div>

      <div className="mb-4">
        <label className="block text-sm text-neutral-400 mb-2">Style</label>
        <div className="flex gap-2">
          {['scroll', 'flash'].map((s) => (
            <button
              key={s}
              type="button"
              onClick={() => setStyle(s)}
              className={`px-4 py-2 rounded-lg text-sm border capitalize transition-colors ${
                style === s
                  ? 'bg-gradient-to-r from-cyan-500 to-blue-600 border-transparent text-white'
                  : 'bg-neutral-900 border-neutral-700 text-neutral-300 hover:border-neutral-500'
              }`}
            >
              {s}
            </button>
          ))}
        </div>
      </div>

      <div className="mb-4">
        <label className="block text-sm text-neutral-400 mb-2">
          Colours ({colors.length}/{MAX_COLORS}) — drag to reorder
        </label>
        <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
          <SortableContext items={ids} strategy={horizontalListSortingStrategy}>
            <div className="flex flex-wrap gap-2">
              {colors.map((hex, i) => (
                <SwatchItem
                  key={ids[i]}
                  id={ids[i]}
                  hex={hex}
                  onChange={(v) => setColor(i, v)}
                  onRemove={() => removeColor(i)}
                  removable={colors.length > 1}
                />
              ))}
              {colors.length < MAX_COLORS && (
                <button
                  type="button"
                  onClick={addColor}
                  className="w-10 h-10 rounded-md border border-dashed border-neutral-600 text-neutral-400 hover:border-cyan-500 hover:text-cyan-400 flex items-center justify-center"
                >
                  <Plus className="w-4 h-4" />
                </button>
              )}
            </div>
          </SortableContext>
        </DndContext>
      </div>

      <div className="mb-3">
        <div className="flex justify-between text-sm text-neutral-400 mb-1">
          <span>Speed</span>
          <span>{speed}</span>
        </div>
        <input
          type="range"
          min={0.1}
          max={5}
          step={0.1}
          value={speed}
          onChange={(e) => setSpeed(parseFloat(e.target.value))}
          className="w-full accent-cyan-500"
        />
      </div>
    </div>
  );
}

function SwatchItem({ id, hex, onChange, onRemove, removable }) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id });
  const style = { transform: CSS.Transform.toString(transform), transition, opacity: isDragging ? 0.6 : 1 };
  return (
    <div ref={setNodeRef} style={style} {...attributes} {...listeners} className="relative group cursor-grab">
      <input
        type="color"
        value={hex}
        onChange={(e) => onChange(e.target.value)}
        onPointerDown={(e) => e.stopPropagation()}
        className="w-10 h-10 rounded-md border border-neutral-700 bg-transparent cursor-pointer"
      />
      {removable && (
        <button
          type="button"
          onClick={onRemove}
          onPointerDown={(e) => e.stopPropagation()}
          className="absolute -top-1.5 -right-1.5 w-4 h-4 rounded-full bg-neutral-800 border border-neutral-600 text-neutral-300 opacity-0 group-hover:opacity-100 flex items-center justify-center"
        >
          <X className="w-2.5 h-2.5" />
        </button>
      )}
    </div>
  );
}
