import React, { useEffect, useState } from 'react';
import { BUILTIN_EFFECTS, getEffectDef, defaultParamsFor } from './effectDefs';
import LedStripPreview from '../shared/LedStripPreview';

// Controlled editor for a built-in effect pattern. Mirrors the
// controlled-component shape of the M1 `CreatePattern.js` component: no
// internal save button, just `initial` to seed state and `onChange` firing
// on every edit — the parent (PatternStudioM2) owns persistence.
export default function EffectEditor({ initial, onChange, className = '' }) {
  const startDef = initial?.effectId ? getEffectDef(initial.effectId) : BUILTIN_EFFECTS[0];
  const [effectId, setEffectId] = useState(startDef.id);
  const [params, setParams] = useState(initial?.params || defaultParamsFor(startDef));

  const effectDef = getEffectDef(effectId);

  function handleSelectEffect(id) {
    const def = getEffectDef(id);
    setEffectId(id);
    setParams(defaultParamsFor(def));
  }

  useEffect(() => {
    onChange?.({ effectId, params });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [effectId, JSON.stringify(params)]);

  function setColor(idx, hex) {
    setParams((p) => {
      const colors = [...(p.colors || [])];
      colors[idx] = hex;
      return { ...p, colors };
    });
  }

  return (
    <div className={className}>
      <div className="mb-4">
        <LedStripPreview
          colors={effectDef.colorSlots ? params.colors : ['#ff6a00', '#ffb703', '#ff0054']}
          paletteStyle="scroll"
          speed={params.speed || 1}
        />
      </div>

      <div className="mb-4">
        <label className="block text-sm text-neutral-400 mb-2">Effect</label>
        <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
          {BUILTIN_EFFECTS.map((e) => (
            <button
              key={e.id}
              type="button"
              onClick={() => handleSelectEffect(e.id)}
              className={`px-3 py-2 rounded-lg text-sm border transition-colors ${
                e.id === effectId
                  ? 'bg-gradient-to-r from-cyan-500 to-blue-600 border-transparent text-white'
                  : 'bg-neutral-900 border-neutral-700 text-neutral-300 hover:border-neutral-500'
              }`}
            >
              {e.label}
            </button>
          ))}
        </div>
      </div>

      {effectDef.colorSlots > 0 && (
        <div className="mb-4">
          <label className="block text-sm text-neutral-400 mb-2">
            {effectDef.colorSlots === 1 ? 'Colour' : `Colours (${effectDef.colorSlots})`}
          </label>
          <div className="flex gap-2">
            {Array.from({ length: effectDef.colorSlots }, (_, i) => (
              <input
                key={i}
                type="color"
                value={params.colors?.[i] || '#ffffff'}
                onChange={(e) => setColor(i, e.target.value)}
                className="w-10 h-10 rounded-md border border-neutral-700 bg-transparent cursor-pointer"
              />
            ))}
          </div>
        </div>
      )}

      {effectDef.hasSpeed && (
        <SliderRow
          label="Speed"
          value={params.speed}
          min={0.1}
          max={5}
          step={0.1}
          onChange={(v) => setParams((p) => ({ ...p, speed: v }))}
        />
      )}
      {effectDef.hasDensity && (
        <SliderRow
          label="Density"
          value={params.density}
          min={0}
          max={100}
          step={1}
          onChange={(v) => setParams((p) => ({ ...p, density: v }))}
        />
      )}
      {effectDef.hasBrightness && (
        <SliderRow
          label="Brightness"
          value={params.brightness}
          min={0}
          max={100}
          step={1}
          onChange={(v) => setParams((p) => ({ ...p, brightness: v }))}
        />
      )}
    </div>
  );
}

function SliderRow({ label, value, min, max, step, onChange }) {
  return (
    <div className="mb-3">
      <div className="flex justify-between text-sm text-neutral-400 mb-1">
        <span>{label}</span>
        <span>{value}</span>
      </div>
      <input
        type="range"
        min={min}
        max={max}
        step={step}
        value={value}
        onChange={(e) => onChange(parseFloat(e.target.value))}
        className="w-full accent-cyan-500"
      />
    </div>
  );
}
