import React, { useEffect, useState } from 'react';

// Lightweight animated LED-strip preview shared by the effect, palette, and
// sequence editors. Plain divs, not canvas — this is an approximation for
// the website editor, not a firmware-accurate renderer.
//
// Usage:
//   <LedStripPreview colors={['#fff']} />                         static
//   <LedStripPreview colors={palette} paletteStyle="scroll" speed={1} />
//   <LedStripPreview frames={[{colors, duration}, ...]} />         sequence
export default function LedStripPreview({
  ledCount = 30,
  colors,
  frames,
  paletteStyle,
  speed = 1,
  height = 28,
  className = '',
}) {
  const animated = (frames && frames.length > 1) || paletteStyle === 'scroll' || paletteStyle === 'flash';
  const [tick, setTick] = useState(0);

  useEffect(() => {
    if (!animated) return;
    const intervalMs = Math.max(60, 400 / Math.max(speed, 0.1));
    const id = setInterval(() => setTick((t) => t + 1), intervalMs);
    return () => clearInterval(id);
  }, [animated, speed]);

  const pixels = buildPixels({ ledCount, colors, frames, paletteStyle, tick });

  return (
    <div
      className={`flex w-full gap-[2px] rounded-lg overflow-hidden bg-neutral-950 p-1 ${className}`}
      style={{ height }}
    >
      {pixels.map((c, i) => (
        <div key={i} className="flex-1 rounded-[2px]" style={{ backgroundColor: c }} />
      ))}
    </div>
  );
}

function buildPixels({ ledCount, colors, frames, paletteStyle, tick }) {
  if (Array.isArray(frames) && frames.length) {
    const frame = frames[tick % frames.length];
    const frameColors = (frame && frame.colors) || [];
    return Array.from({ length: ledCount }, (_, i) => frameColors[i] || '#141414');
  }

  const palette = Array.isArray(colors) && colors.length ? colors : ['#2a2a2a'];

  if (paletteStyle === 'flash') {
    const c = palette[tick % palette.length];
    return Array.from({ length: ledCount }, () => c);
  }

  // 'scroll' tiles + shifts the palette; anything else (static effect
  // preview) tiles it without motion.
  const offset = paletteStyle === 'scroll' ? tick : 0;
  return Array.from({ length: ledCount }, (_, i) => palette[(i + offset) % palette.length]);
}
