// Config for the 11 built-in effects the M2 device firmware supports.
//
// NOTE: exact per-effect firmware parameters (which knobs each effect
// actually reads) aren't documented anywhere in this repo yet — these
// colorSlots/hasSpeed/hasDensity/hasBrightness flags are reasonable
// defaults, not a confirmed firmware spec. If/when the real per-effect
// parameter list shows up, update it here — this is the one place the
// editor UI and the saved `params` shape both derive from.
//
// "Static Colour / Per-Pixel" is deliberately not in this list — it's
// handled by SequenceEditor constrained to a single frame instead of a
// 12th effect entry, so there's only one per-pixel implementation.

export const BUILTIN_EFFECTS = [
  { id: 'fire', label: 'Fire', colorSlots: 1, hasSpeed: true, hasDensity: true, hasBrightness: true },
  { id: 'water', label: 'Water', colorSlots: 1, hasSpeed: true, hasDensity: true, hasBrightness: true },
  { id: 'meteor', label: 'Meteor', colorSlots: 1, hasSpeed: true, hasDensity: true, hasBrightness: true },
  { id: 'lightning', label: 'Lightning', colorSlots: 1, hasSpeed: true, hasDensity: false, hasBrightness: true },
  { id: 'sparkle', label: 'Sparkle', colorSlots: 1, hasSpeed: true, hasDensity: true, hasBrightness: true },
  { id: 'twinkle', label: 'Twinkle', colorSlots: 3, hasSpeed: true, hasDensity: true, hasBrightness: true },
  { id: 'breathing', label: 'Breathing', colorSlots: 1, hasSpeed: true, hasDensity: false, hasBrightness: true },
  { id: 'colourWipe', label: 'Colour Wipe', colorSlots: 1, hasSpeed: true, hasDensity: false, hasBrightness: true },
  { id: 'chase', label: 'Chase', colorSlots: 2, hasSpeed: true, hasDensity: true, hasBrightness: true },
  { id: 'rainbow', label: 'Rainbow', colorSlots: 0, hasSpeed: true, hasDensity: false, hasBrightness: true },
];

const DEFAULT_COLORS = ['#ff2d95', '#7c3aed', '#00f5d4'];

export function getEffectDef(effectId) {
  return BUILTIN_EFFECTS.find((e) => e.id === effectId) || BUILTIN_EFFECTS[0];
}

// Builds a fresh, valid `params` object for an effect definition.
export function defaultParamsFor(effectDef) {
  return {
    colors: DEFAULT_COLORS.slice(0, effectDef.colorSlots),
    ...(effectDef.hasSpeed ? { speed: 1.0 } : {}),
    ...(effectDef.hasDensity ? { density: 50 } : {}),
    ...(effectDef.hasBrightness ? { brightness: 80 } : {}),
  };
}
