import React from 'react';
import { Flame, ListMusic, Film, Square } from 'lucide-react';

// Step 1 of "Create Pattern": choose which kind of pattern to build.
// 'static' is not a distinct saved patternType — it resolves to a
// 'sequence' pattern locked to a single frame (see SequenceEditor's
// `singleFrame` prop), so there's only one per-pixel implementation.
const OPTIONS = [
  {
    key: 'effect',
    label: 'Built-in Effect',
    description: 'Pick one of 10 animated effects (Fire, Rainbow, Chase…) and tune its parameters.',
    icon: Flame,
  },
  {
    key: 'palette',
    label: 'Palette',
    description: 'A custom colour list that scrolls or flashes across the strip.',
    icon: ListMusic,
  },
  {
    key: 'sequence',
    label: 'Sequence',
    description: 'Full frame-by-frame animation — paint any pattern imaginable.',
    icon: Film,
  },
  {
    key: 'static',
    label: 'Static Colour / Per-Pixel',
    description: 'Set every LED to an exact colour, no animation.',
    icon: Square,
  },
];

export default function PatternTypePicker({ isOpen, onClose, onSelect }) {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 px-4">
      <div className="w-full max-w-lg bg-neutral-900 border border-neutral-700 rounded-2xl p-6">
        <h2 className="text-lg font-semibold text-white mb-1">What kind of pattern?</h2>
        <p className="text-sm text-neutral-400 mb-5">You can always create another one later.</p>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          {OPTIONS.map(({ key, label, description, icon: Icon }) => (
            <button
              key={key}
              type="button"
              onClick={() => onSelect(key)}
              aria-label={label}
              className="text-left p-4 rounded-xl border border-neutral-700 bg-neutral-800/50 hover:border-cyan-500 hover:bg-neutral-800 transition-colors"
            >
              <div className="w-9 h-9 rounded-lg bg-gradient-to-br from-cyan-500 to-blue-600 flex items-center justify-center mb-3">
                <Icon className="w-4.5 h-4.5 text-white" />
              </div>
              <div className="text-white font-medium mb-1">{label}</div>
              <div className="text-xs text-neutral-400">{description}</div>
            </button>
          ))}
        </div>

        <button
          type="button"
          onClick={onClose}
          className="mt-5 w-full px-4 py-2 rounded-lg text-sm text-neutral-400 hover:text-white border border-neutral-700 hover:border-neutral-500"
        >
          Cancel
        </button>
      </div>
    </div>
  );
}
