// Shared helpers for the M2 Pattern Studio. Kept framework-agnostic (no React)
// so they're easy to unit test and reuse across editors.

export function generateId() {
  return `m2-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

// Builds a CSS gradient string from a list of hex colors so patterns get a
// reasonable-looking card preview without rendering/uploading a real image.
export function buildPreviewGradient(colors) {
  const list = Array.isArray(colors) && colors.length ? colors : ['#ff2d95', '#7c3aed'];
  if (list.length === 1) {
    return `linear-gradient(135deg, ${list[0]}, ${list[0]})`;
  }
  return `linear-gradient(135deg, ${list.join(', ')})`;
}

export const PATTERN_TYPE_LABELS = {
  effect: 'Built-in Effect',
  palette: 'Palette',
  sequence: 'Sequence',
};

export function todayIso() {
  return new Date().toISOString().slice(0, 10);
}

// Caps a color list down to `max` evenly-sampled stops, so a 30-pixel
// sequence frame doesn't turn into a 30-stop CSS gradient.
export function sampleColors(colors, max = 8) {
  const list = Array.isArray(colors) && colors.length ? colors : ['#ff2d95', '#7c3aed'];
  if (list.length <= max) return list;
  const step = list.length / max;
  return Array.from({ length: max }, (_, i) => list[Math.floor(i * step)]);
}

// Wraps a Firebase promise so a stalled network write/read never hangs the
// UI indefinitely — same shape as the `promiseWithTimeout` helper in
// `Account.js`'s M1 save flow.
export function promiseWithTimeout(promise, ms, label) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error(`${label || 'operation'} timed out after ${ms}ms`)), ms);
    promise
      .then((val) => {
        clearTimeout(timer);
        resolve(val);
      })
      .catch((err) => {
        clearTimeout(timer);
        reject(err);
      });
  });
}
