import React, { useEffect, useMemo, useState } from 'react';
import firebase from 'firebase/compat/app';
import 'firebase/compat/database';
import {
  Search, Plus, Download, Heart, MessageCircle, Trash2, Loader2, X,
} from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import CommentModal from '../shared/CommentModal';
import PatternTypePicker from './PatternTypePicker';
import EffectEditor from './effects/EffectEditor';
import PaletteEditor from './palette/PaletteEditor';
import SequenceEditor from './sequence/SequenceEditor';
import LedStripPreview from './shared/LedStripPreview';
import {
  generateId, buildPreviewGradient, sampleColors, promiseWithTimeout, todayIso, PATTERN_TYPE_LABELS,
} from './shared/patternHelpers';

const gradientBtn = 'bg-gradient-to-r from-cyan-500 via-blue-500 to-indigo-600 text-white hover:opacity-90';
const cardBase = 'bg-neutral-800/50 border border-neutral-700 rounded-2xl overflow-hidden';

// Pattern Studio for the new M2 device (fully-editable effects/palettes/
// sequences). Entirely separate data + UI from the M1 Light Patterns
// feature in `Account.js` — see src/Bible/pattern-studio-m2.md.
export default function PatternStudioM2() {
  const { currentUser, userProfile } = useAuth();

  const [tab, setTab] = useState('mine'); // 'mine' | 'community'
  const [myPatterns, setMyPatterns] = useState([]);
  const [communityPatterns, setCommunityPatterns] = useState([]);
  const [query, setQuery] = useState('');
  const [filter, setFilter] = useState('all'); // all | effect | palette | sequence
  const [sort, setSort] = useState('recent'); // recent | popular | liked

  const [showTypePicker, setShowTypePicker] = useState(false);
  const [editorType, setEditorType] = useState(null); // 'effect' | 'palette' | 'sequence' | 'static'
  const [pendingPattern, setPendingPattern] = useState(null);
  const [title, setTitle] = useState('');
  const [saving, setSaving] = useState(false);
  const [deletingId, setDeletingId] = useState(null);

  const [commentModalOpen, setCommentModalOpen] = useState(false);
  const [selectedForComments, setSelectedForComments] = useState(null);

  // Realtime listeners, mirroring Account.js's `uploads/{uid}` subscription
  // pattern, but against the fully separate m2Uploads / m2CommunityPatterns
  // roots.
  useEffect(() => {
    if (!currentUser) return undefined;
    const db = firebase.database();
    const ref = db.ref(`m2Uploads/${currentUser.uid}`);
    const handler = (snap) => {
      const val = snap.val();
      setMyPatterns(val ? Object.keys(val).map((k) => ({ id: k, ...val[k] })) : []);
    };
    ref.on('value', handler);
    return () => ref.off('value', handler);
  }, [currentUser]);

  useEffect(() => {
    const db = firebase.database();
    const ref = db.ref('m2CommunityPatterns');
    const handler = (snap) => {
      const val = snap.val();
      setCommunityPatterns(val ? Object.keys(val).map((k) => ({ id: k, ...val[k] })) : []);
    };
    ref.on('value', handler);
    return () => ref.off('value', handler);
  }, []);

  const list = tab === 'mine' ? myPatterns : communityPatterns;

  const filteredList = useMemo(() => {
    let items = list;
    if (filter !== 'all') items = items.filter((i) => i.patternType === filter);
    if (query.trim()) {
      const q = query.trim().toLowerCase();
      items = items.filter((i) => (i.title || '').toLowerCase().includes(q));
    }
    const sorted = [...items];
    if (sort === 'popular') sorted.sort((a, b) => (b.downloads || 0) - (a.downloads || 0));
    else if (sort === 'liked') sorted.sort((a, b) => (b.likes || 0) - (a.likes || 0));
    else sorted.sort((a, b) => (b.updatedAt || '').localeCompare(a.updatedAt || ''));
    return sorted;
  }, [list, filter, query, sort]);

  function openTypePicker() {
    setShowTypePicker(true);
  }

  function handleTypeSelected(type) {
    setEditorType(type);
    setShowTypePicker(false);
    setPendingPattern(null);
    setTitle('');
  }

  function closeCreateFlow() {
    setEditorType(null);
    setPendingPattern(null);
    setTitle('');
  }

  async function handleSave() {
    if (!currentUser || !editorType || !pendingPattern) return;
    setSaving(true);

    const id = generateId();
    const patternType = editorType === 'static' ? 'sequence' : editorType;

    let typeSpecific;
    let representativeColors;
    if (patternType === 'effect') {
      typeSpecific = { effect: pendingPattern };
      representativeColors = pendingPattern.params?.colors?.length
        ? pendingPattern.params.colors
        : ['#ff6a00', '#ffb703', '#ff0054'];
    } else if (patternType === 'palette') {
      typeSpecific = { palette: pendingPattern };
      representativeColors = pendingPattern.colors;
    } else {
      typeSpecific = { sequence: pendingPattern };
      representativeColors = sampleColors(pendingPattern.frames?.[0]?.colors);
    }

    const newItem = {
      id,
      model: 'm2',
      patternType,
      title: title.trim() || `Pattern ${id.slice(-5)}`,
      downloads: 0,
      likes: 0,
      comments: 0,
      updatedAt: todayIso(),
      preview: buildPreviewGradient(representativeColors),
      ...typeSpecific,
    };

    try {
      await promiseWithTimeout(
        firebase.database().ref(`m2Uploads/${currentUser.uid}/${id}`).set(newItem),
        8000,
        'm2Uploads set'
      );
      closeCreateFlow();
    } catch (e) {
      console.warn('PatternStudioM2: failed to save pattern to m2Uploads', e);
    }

    try {
      const ownerUsername =
        userProfile?.username || currentUser?.displayName || currentUser?.email?.split('@')[0] || 'Unknown';
      const communityItem = { ...newItem, ownerId: currentUser.uid, ownerUsername, sourceUploadId: id };
      await promiseWithTimeout(
        firebase.database().ref(`m2CommunityPatterns/${id}`).set(communityItem),
        8000,
        'm2CommunityPatterns set'
      );
    } catch (e) {
      // Best-effort, same as M1: a community mirror failure must never undo
      // the personal save above, which already succeeded/failed on its own.
      console.warn('PatternStudioM2: failed to mirror pattern to m2CommunityPatterns', e);
    }

    setSaving(false);
  }

  async function handleDelete(item) {
    if (!currentUser) return;
    setDeletingId(item.id);
    try {
      await firebase.database().ref(`m2Uploads/${currentUser.uid}/${item.id}`).remove();
    } catch (e) {
      console.warn('PatternStudioM2: failed to delete from m2Uploads', e);
    }
    try {
      await firebase.database().ref(`m2CommunityPatterns/${item.id}`).remove();
    } catch (e) {
      console.warn('PatternStudioM2: failed to delete from m2CommunityPatterns', e);
    }
    setDeletingId(null);
  }

  async function handleDownload(item) {
    if (!currentUser) return;
    const newId = generateId();
    const { id: _id, ownerId: _ownerId, ownerUsername: _ownerUsername, sourceUploadId: _src, ...rest } = item;
    const myCopy = {
      ...rest,
      id: newId,
      downloads: 0,
      likes: 0,
      comments: 0,
      updatedAt: todayIso(),
      sourceCommunityId: item.id,
    };
    try {
      await firebase.database().ref(`m2Uploads/${currentUser.uid}/${newId}`).set(myCopy);
    } catch (e) {
      console.warn('PatternStudioM2: failed to save downloaded pattern', e);
      return;
    }
    try {
      await firebase.database().ref(`m2CommunityPatterns/${item.id}/downloads`).transaction((cur) => (cur || 0) + 1);
    } catch (e) {
      console.warn('PatternStudioM2: failed to bump download count', e);
    }
  }

  async function handleLike(item) {
    if (!currentUser) return;
    try {
      await firebase.database().ref(`m2CommunityPatterns/${item.id}/likes`).transaction((cur) => (cur || 0) + 1);
    } catch (e) {
      console.warn('PatternStudioM2: failed to like pattern', e);
    }
  }

  async function handleSubmitComment(text) {
    if (!selectedForComments || !currentUser) return;
    const db = firebase.database();

    let username = 'Anonymous';
    try {
      const snap = await db.ref(`users/${currentUser.uid}`).once('value');
      username = snap.val()?.username || currentUser.displayName || 'Anonymous';
    } catch (e) {
      username = currentUser.displayName || 'Anonymous';
    }

    const commentId = Math.random().toString(36).slice(2, 9);
    await db.ref(`comments/${selectedForComments.id}/${commentId}`).set({
      id: commentId,
      userId: currentUser.uid,
      displayName: username,
      text,
      createdAt: Date.now(),
    });

    const commentsSnap = await db.ref(`comments/${selectedForComments.id}`).once('value');
    const count = commentsSnap.exists() ? Object.keys(commentsSnap.val()).length : 0;

    // Best-effort: keep both the community mirror and (if it's the current
    // user's own pattern) their personal copy's comment count in sync.
    try {
      await db.ref(`m2CommunityPatterns/${selectedForComments.id}/comments`).set(count);
    } catch (e) { /* not every item has a community mirror the caller can write to */ }
    if (currentUser) {
      try {
        await db.ref(`m2Uploads/${currentUser.uid}/${selectedForComments.id}/comments`).set(count);
      } catch (e) { /* fine if this user doesn't own this item */ }
    }
  }

  if (!currentUser) return null;

  return (
    <div className="max-w-7xl mx-auto px-4 pb-16">
      <div className="flex flex-wrap items-center justify-between gap-4 mb-6">
        <div>
          <div className="inline-flex items-center gap-2 px-2.5 py-0.5 rounded-full bg-cyan-500/10 border border-cyan-500/30 text-cyan-400 text-xs font-medium mb-2">
            M2 · New Device
          </div>
          <h1 className="text-2xl font-bold text-white">Pattern Studio</h1>
          <p className="text-neutral-400 text-sm">Design effects, palettes, and full sequences for your M2 device.</p>
        </div>
        <button
          type="button"
          onClick={openTypePicker}
          className={`inline-flex items-center gap-2 px-4 py-2.5 rounded-xl font-medium ${gradientBtn}`}
        >
          <Plus className="w-4 h-4" />
          Create Pattern
        </button>
      </div>

      <div className="flex gap-2 mb-4">
        {[
          { key: 'mine', label: 'My Patterns' },
          { key: 'community', label: 'Community' },
        ].map((t) => (
          <button
            key={t.key}
            type="button"
            onClick={() => setTab(t.key)}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
              tab === t.key ? 'bg-neutral-800 text-white border border-neutral-600' : 'text-neutral-400 hover:text-white'
            }`}
          >
            {t.label}
          </button>
        ))}
      </div>

      <div className="flex flex-wrap gap-3 mb-6">
        <div className="relative flex-1 min-w-[180px]">
          <Search className="w-4 h-4 text-neutral-500 absolute left-3 top-1/2 -translate-y-1/2" />
          <input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search patterns…"
            className="w-full pl-9 pr-3 py-2 bg-neutral-900 border border-neutral-700 rounded-lg text-white text-sm focus:border-cyan-500 focus:outline-none"
          />
        </div>
        <select
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
          className="px-3 py-2 bg-neutral-900 border border-neutral-700 rounded-lg text-white text-sm"
        >
          <option value="all">All types</option>
          <option value="effect">Effects</option>
          <option value="palette">Palettes</option>
          <option value="sequence">Sequences</option>
        </select>
        <select
          value={sort}
          onChange={(e) => setSort(e.target.value)}
          className="px-3 py-2 bg-neutral-900 border border-neutral-700 rounded-lg text-white text-sm"
        >
          <option value="recent">Most recent</option>
          <option value="popular">Most downloaded</option>
          <option value="liked">Most liked</option>
        </select>
      </div>

      {filteredList.length === 0 ? (
        <div className="text-center py-16 text-neutral-500">
          {tab === 'mine' ? 'No patterns yet — create your first one.' : 'No community patterns match yet.'}
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {filteredList.map((item) => (
            <PatternCard
              key={item.id}
              item={item}
              tab={tab}
              deleting={deletingId === item.id}
              onDelete={() => handleDelete(item)}
              onDownload={() => handleDownload(item)}
              onLike={() => handleLike(item)}
              onComment={() => {
                setSelectedForComments(item);
                setCommentModalOpen(true);
              }}
            />
          ))}
        </div>
      )}

      <PatternTypePicker
        isOpen={showTypePicker}
        onClose={() => setShowTypePicker(false)}
        onSelect={handleTypeSelected}
      />

      {editorType && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 px-4 py-6 overflow-y-auto">
          <div className="w-full max-w-2xl bg-neutral-900 border border-neutral-700 rounded-2xl p-6 my-auto">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-semibold text-white">
                New {PATTERN_TYPE_LABELS[editorType === 'static' ? 'sequence' : editorType]}
                {editorType === 'static' ? ' (Static)' : ''}
              </h2>
              <button type="button" onClick={closeCreateFlow} className="text-neutral-400 hover:text-white">
                <X className="w-5 h-5" />
              </button>
            </div>

            <input
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="Pattern title"
              className="w-full mb-4 px-3 py-2 bg-neutral-950 border border-neutral-700 rounded-lg text-white text-sm focus:border-cyan-500 focus:outline-none"
            />

            {editorType === 'effect' && <EffectEditor onChange={setPendingPattern} />}
            {editorType === 'palette' && <PaletteEditor onChange={setPendingPattern} />}
            {editorType === 'sequence' && <SequenceEditor onChange={setPendingPattern} />}
            {editorType === 'static' && <SequenceEditor singleFrame onChange={setPendingPattern} />}

            <div className="flex justify-end gap-2 mt-6">
              <button
                type="button"
                onClick={closeCreateFlow}
                className="px-4 py-2 rounded-lg text-sm text-neutral-400 hover:text-white border border-neutral-700 hover:border-neutral-500"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={handleSave}
                disabled={saving || !pendingPattern}
                className={`px-4 py-2 rounded-lg text-sm font-medium ${gradientBtn} ${
                  saving || !pendingPattern ? 'opacity-60 cursor-not-allowed' : ''
                }`}
              >
                {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Save Pattern'}
              </button>
            </div>
          </div>
        </div>
      )}

      <CommentModal
        isOpen={commentModalOpen}
        onClose={() => setCommentModalOpen(false)}
        currentUserId={currentUser?.uid}
        creatorUserId={selectedForComments?.ownerId || currentUser?.uid}
        patternId={selectedForComments?.id}
        onSubmitComment={handleSubmitComment}
      />
    </div>
  );
}

function PatternCard({ item, tab, deleting, onDelete, onDownload, onLike, onComment }) {
  return (
    <div className={cardBase}>
      <div className="h-24" style={{ background: item.preview }}>
        {(item.patternType === 'sequence' && item.sequence?.frames?.length > 1) ||
        (item.patternType === 'palette' && item.palette?.style) ? (
          <div className="p-2 h-full flex items-end">
            <LedStripPreview
              ledCount={item.patternType === 'sequence' ? item.sequence?.ledCount || 30 : 30}
              colors={item.patternType === 'palette' ? item.palette.colors : undefined}
              paletteStyle={item.patternType === 'palette' ? item.palette.style : undefined}
              frames={item.patternType === 'sequence' ? item.sequence.frames : undefined}
              speed={item.patternType === 'palette' ? item.palette.speed : 1}
              height={20}
              className="opacity-90"
            />
          </div>
        ) : null}
      </div>
      <div className="p-4">
        <div className="flex items-center justify-between mb-1">
          <h3 className="text-white font-medium truncate">{item.title}</h3>
          <span className="text-[10px] uppercase tracking-wide text-cyan-400 bg-cyan-500/10 px-1.5 py-0.5 rounded">
            {PATTERN_TYPE_LABELS[item.patternType] || item.patternType}
          </span>
        </div>
        {tab === 'community' && (
          <p className="text-xs text-neutral-500 mb-2">by {item.ownerUsername || 'Unknown'}</p>
        )}
        <div className="flex items-center gap-3 text-xs text-neutral-400 mb-3">
          <span className="inline-flex items-center gap-1">
            <Download className="w-3 h-3" /> {item.downloads || 0}
          </span>
          <span className="inline-flex items-center gap-1">
            <Heart className="w-3 h-3" /> {item.likes || 0}
          </span>
          <span className="inline-flex items-center gap-1">
            <MessageCircle className="w-3 h-3" /> {item.comments || 0}
          </span>
        </div>
        <div className="flex gap-2">
          {tab === 'mine' ? (
            <button
              type="button"
              onClick={onDelete}
              disabled={deleting}
              className="flex-1 inline-flex items-center justify-center gap-1.5 px-3 py-1.5 rounded-lg text-xs bg-neutral-900 border border-neutral-700 text-neutral-300 hover:border-red-500 hover:text-red-400"
            >
              {deleting ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Trash2 className="w-3.5 h-3.5" />}
              Delete
            </button>
          ) : (
            <>
              <button
                type="button"
                onClick={onDownload}
                className="flex-1 inline-flex items-center justify-center gap-1.5 px-3 py-1.5 rounded-lg text-xs bg-neutral-900 border border-neutral-700 text-neutral-300 hover:border-cyan-500 hover:text-cyan-400"
              >
                <Download className="w-3.5 h-3.5" />
                Download
              </button>
              <button
                type="button"
                onClick={onLike}
                className="px-3 py-1.5 rounded-lg text-xs bg-neutral-900 border border-neutral-700 text-neutral-300 hover:border-pink-500 hover:text-pink-400"
              >
                <Heart className="w-3.5 h-3.5" />
              </button>
            </>
          )}
          <button
            type="button"
            onClick={onComment}
            className="px-3 py-1.5 rounded-lg text-xs bg-neutral-900 border border-neutral-700 text-neutral-300 hover:border-neutral-500"
          >
            <MessageCircle className="w-3.5 h-3.5" />
          </button>
        </div>
      </div>
    </div>
  );
}
